create or replace function public.project_attribution_event(p_user_id uuid,p_funnel_id text,p_session_key text,p_event_type text,p_payload jsonb default '{}'::jsonb) returns uuid language plpgsql security definer set search_path=public as $$ declare v_id uuid; v_source text; v_medium text; v_campaign text; v_content text; v_term text; v_click text; v_url text; begin if p_user_id is null or p_funnel_id is null or p_session_key is null or length(trim(p_session_key))=0 then return null; end if; v_source=nullif(p_payload->>'source',''); v_medium=nullif(p_payload->>'medium',''); v_campaign=nullif(p_payload->>'campaign',''); v_content=nullif(p_payload->>'content',''); v_term=nullif(p_payload->>'term',''); v_click=nullif(p_payload->>'click_id',''); v_url=nullif(p_payload->>'landing_url',''); insert into public.attribution_sessions(user_id,funnel_id,session_key,source,medium,campaign,content,term,click_id,landing_url,first_seen_at,last_seen_at,metadata) values(p_user_id,p_funnel_id,p_session_key,v_source,v_medium,v_campaign,v_content,v_term,v_click,v_url,now(),now(),coalesce(p_payload,'{}'::jsonb)) on conflict (user_id,funnel_id,session_key) do update set source=coalesce(public.attribution_sessions.source,excluded.source),medium=coalesce(public.attribution_sessions.medium,excluded.medium),campaign=coalesce(public.attribution_sessions.campaign,excluded.campaign),content=coalesce(public.attribution_sessions.content,excluded.content),term=coalesce(public.attribution_sessions.term,excluded.term),click_id=coalesce(public.attribution_sessions.click_id,excluded.click_id),landing_url=coalesce(public.attribution_sessions.landing_url,excluded.landing_url),last_seen_at=now(),metadata=coalesce(public.attribution_sessions.metadata,'{}'::jsonb)||coalesce(excluded.metadata,'{}'::jsonb) returning id into v_id; return v_id; end $$; revoke all on function public.project_attribution_event(uuid,text,text,text,jsonb) from public,anon,authenticated; grant execute on function public.project_attribution_event(uuid,text,text,text,jsonb) to service_role;